@Component("clinicalOrder-handler")
@ProcessingGroup("clinicalOrder-processing-group")
public class ClinicalOrderEventHandler {
	
	// core constructor
	ClinicalOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateClinicalOrderEvent
     */
    @EventHandler
    public void handle( CreateClinicalOrderEvent event) {
        entityManager.persist(new ClinicalOrder(event.getClinicalOrderId(), event.getOrderNumber(), event.getPatient(), event.getEncounter(), event.getOrderingClinician(), event.getMedicationOrders(), event.getLaboratoryOrders(), event.getImagingOrders(), event.getProcedureOrders(), event.getAuthorizations(), event.getStatus(), event.getOrderType(), event.getPriority()));
    }

    /*
     * @param	event UpdateClinicalOrderEvent
     */
    @EventHandler
    public ClinicalOrder handle( UpdateClinicalOrderEvent event) {
    	entityManager.merge(new ClinicalOrder(event.getClinicalOrderId(), event.getOrderNumber(), event.getPatient(), event.getEncounter(), event.getOrderingClinician(), event.getMedicationOrders(), event.getLaboratoryOrders(), event.getImagingOrders(), event.getProcedureOrders(), event.getAuthorizations(), event.getStatus(), event.getOrderType(), event.getPriority()));
    }
    
    /*
     * @param	event DeleteClinicalOrderEvent
     */
    @EventHandler
    public void on( DeleteClinicalOrderEvent event) {
    	ClinicalOrder entity = new ClinicalOrder();
   
    	// ------------------------------------------
    	// apply the ClinicalOrderId
    	// ------------------------------------------
    	entity.setClinicalOrderId( event.getClinicalOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ClinicalOrderRepository clinicalOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ClinicalOrderEventHandler.class.getName());

}
